/**
 * One-off, re-runnable repair: remove the synthetic seed prices and the
 * synthetic 90-day price history that a `seedDatabase()` run left in the
 * PRODUCTION `current_prices` / `price_points` tables on 2026-07-07.
 *
 * ## What happened
 *
 * `src/lib/server/db/seed.ts` exists to boot a fresh database with the same
 * deterministic fixture catalog the frontend was built against. For every
 * fixture row it writes a `current_prices` row and — the part that matters
 * here — `historyDays = 90` daily `price_points` generated by `priceSeries()`,
 * a seeded pseudo-random walk. It is guarded (`if (!skusEmpty && !force)`),
 * so it can only have touched a populated production catalog with
 * `FORCE_RESEED=true`.
 *
 * It did, once. The evidence is exact:
 *
 *   - 158 `current_prices` rows carry an `updated_at` inside a single
 *     seven-second window, **2026-07-07 13:53:40 → 13:53:46 UTC**. One
 *     script run, not 158 admin saves.
 *   - All 158 have `updated_by IS NULL`. The seeder stamps `'u-admin'` only
 *     when it also seeded that user, which it refuses to do in production
 *     without `DEV_ADMIN_MOBILE` — so a null updater is that branch's
 *     signature. (The same file's own comment records that "the first prod
 *     force-reseed failed" on this FK, so a prod force-reseed is documented.)
 *   - Every one of the 243 fixture SKUs — id equal to slug, because the
 *     seeder writes `id: row.slug` while every catalog SKU created since gets
 *     a ULID — carries exactly 90–91 `price_points`, one per day from
 *     2026-04-09 to 2026-07-07 and none after. Mean absolute day-over-day
 *     move 0.58%. Real prices in this table arrive irregularly, several a day
 *     or none for a week.
 *   - For all 158, `current_prices.price` equals the last point of that walk,
 *     which is how the seeder writes it.
 *
 * One row inside the same date window is **not** seed data and is left alone:
 * `rebar-deformed-1` («میلگرد آجدار ۱۰»), saved by the admin امیر at
 * 17:11:11 the same evening, three hours after the run, at a price the
 * fixture does not contain. That is an ordinary stale price on an inactive
 * SKU, not this bug.
 *
 * ## Why it matters, precisely
 *
 * The stale-price gate does its job on the NUMBER: `getPriceFreshness`
 * withholds anything older than `PRICE_STALE_HIDE_AFTER_DAYS` (2 business
 * days), so the price tables render «تماس بگیرید» and the public DTO ships
 * `price: 0, priceHidden: true`. No customer can read the seed price off a
 * price table.
 *
 * The CHART has no such gate. `GET /api/sku/{slug}/history` and the
 * server-rendered `PriceChart` read `price_points` directly, so on the
 * ۳ ماه and سال ranges a live product page publishes ninety days of invented
 * prices, with a caption that states two of them in Persian numerals:
 *
 *     نمودار قیمت در ماه؛ از ۳۸٬۳۹۱ تومان به ۴۰٬۸۰۰ تومان
 *
 * That is the actual customer-facing exposure, and it exists on all 243
 * fixture SKUs — including the 84 whose current price has since been
 * corrected by an admin or by the mirror, and whose charts therefore splice a
 * real price onto a fabricated 90-day run-up.
 *
 * ## What this script does
 *
 *  1. **Deletes every fabricated `price_points` row** — the 2026-04-09 →
 *     2026-07-07 window, restricted to fixture-id SKUs. Nothing else in the
 *     table falls inside it (verified: 21,871 of 21,871 points in that window
 *     belong to fixture SKUs).
 *  2. **Deletes the 158 seed `current_prices` rows.**
 *  3. **Re-prices what can be re-priced**, by running the production matcher
 *     (`matchSku`, same gates and same live ahanonline fetch as the twice-daily
 *     mirror) over the active ones and saving only `write:exact` results
 *     through `savePrice`, which writes the audit entry and a genuine
 *     price point.
 *
 * Anything the matcher will not vouch for is left with **no `current_prices`
 * row at all**. That is this repo's established "we do not know this price"
 * state, not a workaround: PR #230 added `listActiveSkuIdsWithoutPrice()`, the
 * urgent «کالای بدون قیمت» dashboard tile and the `?unpriced=1` pricing-grid
 * filter precisely so an unpriced active SKU is visible to the owner, and
 * `CatalogManager` badges each one «بدون قیمت». The public page renders
 * «تماس بگیرید», which is the lead-gen state the product is built on. A
 * fabricated number is strictly worse than that in every direction, so no
 * price is ever estimated here.
 *
 * Deleting rather than zeroing is deliberate for the same reason: a price of
 * 0 is invisible to the unpriced tile (it counts `current_prices` rows) and
 * indistinguishable in the grid from a stale-hidden real price.
 *
 * ## Running it
 *
 *   docker compose exec -T web node scripts/repairSeedPrices.mjs        # dry run
 *   docker compose exec -T web node scripts/repairSeedPrices.mjs --apply
 *
 * or, from a checkout with node_modules:
 *
 *   DATABASE_URL=… ./node_modules/.bin/tsx scripts/repairSeedPrices.ts [--apply]
 *
 * Dry run by default: it reports exactly what it would delete and what the
 * matcher would write, and touches nothing. `--no-fetch` skips the live
 * ahanonline pass (deletes only) when the source is unreachable — the SKUs it
 * would have re-priced simply stay unpriced and surface on the tile.
 *
 * Re-runnable: after a successful `--apply` the detection query matches
 * nothing and a second run is a no-op.
 */
import { and, eq, gte, inArray, lte, sql } from 'drizzle-orm';

import { getDb, hasDb } from '../src/lib/server/db/client';
import { currentPrices, pricePoints, skus, categories, subCategories } from '../src/lib/server/db/schema';
import { fetchAhanonlinePrices } from '../src/lib/server/integrations/ahanonline';
import {
  DEFAULT_MATCH_CONFIG,
  SOURCE_PATHS,
  WRITE_REASON,
  matchSku,
  taxonomyKey,
  type MatchConfig,
  type MatchableSku,
} from '../src/lib/server/services/priceSync.match';
import { savePrice } from '../src/lib/server/services/pricing.service';
import { jalaliDayKey } from '../src/lib/server/utils/jalali';

/** The seven-second window the single `seedDatabase()` run wrote in. Bounded
 *  tightly on purpose: it is what separates the 158 seeded rows from the one
 *  genuine admin save three hours later the same day. */
const SEED_RUN_FROM = new Date('2026-07-07T13:53:00.000Z');
const SEED_RUN_TO = new Date('2026-07-07T13:54:00.000Z');

/** The generated history window: `historyDays = 90` ending at the run. */
const SEED_HISTORY_FROM = new Date('2026-04-09T00:00:00.000Z');
const SEED_HISTORY_TO = new Date('2026-07-07T23:59:59.999Z');

/** Fixture SKUs are the ones the seeder created, and it uses the slug as the
 *  id. Everything created through the panel since gets a ULID. */
const FIXTURE_ID = sql`${skus.id} !~ '^[0-9A-HJKMNP-TV-Z]{26}$'`;

interface SeedRow extends MatchableSku {
  price: number;
  isActive: boolean;
  categoryName: string;
  subCategoryName: string;
  skuName: string;
}

function todayJalaliTriple(now: Date): [number, number, number] {
  const [y, m, d] = jalaliDayKey(now).split('-').map(Number);
  return [y!, m!, d!];
}

async function loadSeedRows(): Promise<SeedRow[]> {
  const rows = await getDb()
    .select({
      id: skus.id,
      name: skus.name,
      size: skus.size,
      factory: skus.factory,
      priceBasis: skus.priceBasis,
      isActive: skus.isActive,
      price: currentPrices.price,
      categorySlug: categories.slug,
      subCategorySlug: subCategories.slug,
      categoryName: categories.name,
      subCategoryName: subCategories.name,
    })
    .from(currentPrices)
    .innerJoin(skus, eq(skus.id, currentPrices.skuId))
    .innerJoin(categories, eq(categories.id, skus.categoryId))
    .innerJoin(subCategories, eq(subCategories.id, skus.subCategoryId))
    .where(
      and(
        gte(currentPrices.updatedAt, SEED_RUN_FROM),
        lte(currentPrices.updatedAt, SEED_RUN_TO),
        sql`${currentPrices.updatedBy} is null`,
        FIXTURE_ID,
      ),
    )
    .orderBy(categories.name, subCategories.name, skus.id);

  return rows.map((r) => ({ ...r, skuName: r.name }));
}

/** Every fixture SKU that still carries generated history, priced or not. */
async function countFabricatedPoints(): Promise<{ points: number; skuIds: string[] }> {
  const rows = await getDb()
    .select({ skuId: pricePoints.skuId, n: sql<number>`count(*)::int` })
    .from(pricePoints)
    .innerJoin(skus, eq(skus.id, pricePoints.skuId))
    .where(and(gte(pricePoints.at, SEED_HISTORY_FROM), lte(pricePoints.at, SEED_HISTORY_TO), FIXTURE_ID))
    .groupBy(pricePoints.skuId);
  return {
    points: rows.reduce((sum, r) => sum + r.n, 0),
    skuIds: rows.map((r) => r.skuId),
  };
}

interface MatchOutcome {
  skuId: string;
  price: number | null;
  reason: string;
  matchedName: string | null;
  matchedFactory: string | null;
  sourceUpdatedAt: string | null;
}

async function runMatcher(seedRows: SeedRow[], now: Date): Promise<MatchOutcome[]> {
  const active = seedRows.filter((r) => r.isActive);
  const paths = new Set<string>();
  for (const r of active) for (const p of SOURCE_PATHS[taxonomyKey(r)] ?? []) paths.add(p);
  if (paths.size === 0) return [];

  console.log(`[repair] fetching ${paths.size} ahanonline pages for ${active.length} active SKUs…`);
  const { rows, failures, pagesFetched } = await fetchAhanonlinePrices({ paths: [...paths], delayMs: 1200 });
  console.log(`[repair] ${pagesFetched} pages, ${rows.length} source rows, ${failures.length} failures`);
  for (const f of failures) console.warn(`[repair]   page failed: ${f.path} — ${f.error}`);

  const config: MatchConfig = { ...DEFAULT_MATCH_CONFIG, now };
  const today = todayJalaliTriple(now);
  return active.map((sku) => {
    const result = matchSku(sku, rows, config, today);
    return {
      skuId: sku.id,
      price: result.ok ? result.priceToman : null,
      reason: result.reason,
      matchedName: result.row?.name ?? null,
      matchedFactory: result.factory,
      sourceUpdatedAt: result.sourceUpdatedAt,
    };
  });
}

async function main(): Promise<number> {
  const apply = process.argv.includes('--apply');
  const noFetch = process.argv.includes('--no-fetch');
  const now = new Date();

  if (!hasDb()) {
    console.error('[repair] DATABASE_URL is not set.');
    return 1;
  }

  const seedRows = await loadSeedRows();
  const history = await countFabricatedPoints();

  console.log(`\n[repair] ${apply ? 'APPLY' : 'DRY RUN'} — nothing is written until --apply is passed.\n`);
  console.log(`[repair] seed current_prices rows : ${seedRows.length}`);
  console.log(`[repair]   of which active SKUs   : ${seedRows.filter((r) => r.isActive).length}`);
  console.log(`[repair] fabricated price_points  : ${history.points} across ${history.skuIds.length} SKUs\n`);

  if (seedRows.length === 0 && history.points === 0) {
    console.log('[repair] nothing to do — already repaired.');
    return 0;
  }

  const byCategory = new Map<string, SeedRow[]>();
  for (const r of seedRows) {
    const list = byCategory.get(r.categoryName) ?? [];
    list.push(r);
    byCategory.set(r.categoryName, list);
  }
  for (const [cat, list] of byCategory) {
    const act = list.filter((r) => r.isActive).length;
    console.log(`[repair]   ${cat}: ${list.length} rows (${act} active)`);
  }

  const outcomes = noFetch ? [] : await runMatcher(seedRows, now);
  const writable = outcomes.filter((o) => o.price !== null && o.reason === WRITE_REASON);

  console.log(`\n[repair] matcher: ${writable.length} confident price(s) of ${outcomes.length} active SKUs considered`);
  const reasons = new Map<string, number>();
  for (const o of outcomes) reasons.set(o.reason, (reasons.get(o.reason) ?? 0) + 1);
  for (const [reason, n] of [...reasons].sort((a, b) => b[1] - a[1])) {
    console.log(`[repair]   ${reason}: ${n}`);
  }
  const nameById = new Map(seedRows.map((r) => [r.id, r.skuName]));
  for (const w of writable) {
    console.log(
      `[repair]   WRITE ${w.skuId} «${nameById.get(w.skuId)}» ← ${w.price} تومان/kg ` +
        `(«${w.matchedName}», ${w.matchedFactory}, ${w.sourceUpdatedAt})`,
    );
  }

  const willUnprice = seedRows.filter(
    (r) => r.isActive && !writable.some((w) => w.skuId === r.id),
  );
  console.log(
    `\n[repair] would delete ${seedRows.length} seed price row(s); ` +
      `${willUnprice.length} active SKU(s) end up «بدون قیمت», ` +
      `${seedRows.length - seedRows.filter((r) => r.isActive).length} are on inactive SKUs.`,
  );

  if (!apply) {
    console.log('\n[repair] dry run — no changes made. Re-run with --apply.');
    return 0;
  }

  // ---- delete, in one transaction ----------------------------------------
  // History first, then the prices: `savePrice` below computes movement% off
  // `price_points`, and a fabricated baseline would publish a +120% نوسان on
  // a price that never moved.
  const db = getDb();
  const deleted = await db.transaction(async (tx) => {
    const pts = await tx
      .delete(pricePoints)
      .where(
        and(
          gte(pricePoints.at, SEED_HISTORY_FROM),
          lte(pricePoints.at, SEED_HISTORY_TO),
          inArray(
            pricePoints.skuId,
            tx.select({ id: skus.id }).from(skus).where(FIXTURE_ID),
          ),
        ),
      )
      .returning({ id: pricePoints.id });

    const prices =
      seedRows.length === 0
        ? []
        : await tx
            .delete(currentPrices)
            .where(
              inArray(
                currentPrices.skuId,
                seedRows.map((r) => r.id),
              ),
            )
            .returning({ skuId: currentPrices.skuId });

    return { points: pts.length, prices: prices.length };
  });
  console.log(`\n[repair] deleted ${deleted.points} fabricated price point(s), ${deleted.prices} seed price row(s).`);

  // ---- re-price what the matcher vouches for ------------------------------
  // `savePrice` opens its own transaction per SKU (it takes a per-SKU advisory
  // lock), so this cannot join the delete above. If one fails the SKU is left
  // unpriced, which is the safe outcome.
  let written = 0;
  for (const w of writable) {
    try {
      await savePrice(null, { skuId: w.skuId, price: w.price! });
      written += 1;
    } catch (err) {
      console.error(`[repair]   write failed for ${w.skuId}: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  console.log(`[repair] wrote ${written} real price(s).`);
  console.log('[repair] done.');
  return 0;
}

main()
  .then((code) => process.exit(code))
  .catch((err) => {
    console.error('[repair] crashed:', err);
    process.exit(1);
  });
